            newValue = getConvertUtils().convert((String) value,
                                            type.getComponentType());
        } else if (value instanceof String[]) {
            newValue = getConvertUtils().convert(((String[]) value)[0],
                                            type.getComponentType());
        } else {
            newValue = convert(value, type.getComponentType());
        }
